function rotatedDigits(n) {
  let count = 0;

  for (let x = 1; x <= n; x++) {
    let value = x;
    let valid = true;
    let changed = false;

    while (value > 0 && valid) {
      const digit = value % 10;
      if (digit === 3 || digit === 4 || digit === 7) {
        valid = false;
      } else if (digit === 2 || digit === 5 || digit === 6 || digit === 9) {
        changed = true;
      }
      value = Math.floor(value / 10);
    }

    if (valid && changed) {
      count++;
    }
  }
  return count;
}

