function rotatedDigits(n) {
  const turn = { '0': '0', '1': '1', '8': '8', '2': '5', '5': '2', '6': '9', '9': '6' };
  let total = 0;
  for (let x = 1; x <= n; x++) {
    const original = String(x);
    let rotated = '';
    let ok = true;
    for (const ch of original) {
      if (!(ch in turn)) { ok = false; break; }
      rotated += turn[ch];
    }
    if (ok && rotated !== original) total++;
  }
  return total;
}

